WITH fixes(slug,pos,why) AS (VALUES ('penal-erros-tentativa-dolo-fixacao',4,'Correto. O art. 14, II, do Código Penal define tentativa quando, iniciada a execução, o crime não se consuma por circunstâncias alheias à vontade do agente.'),('penal-lei-no-espaco',7,'Correto. O art. 8º do Código Penal determina que a pena cumprida no estrangeiro pelo mesmo crime seja computada na pena imposta no Brasil quando idênticas, ou atenuada quando diversas.'),('penal-lei-no-tempo',7,'Correto. O art. 3º do Código Penal estabelece que a lei temporária ou excepcional continua aplicável ao fato praticado durante sua vigência, mesmo após cessar sua duração ou circunstância.'),('penal-confissao-sumulas-545-630',11,'Errado. A existência de outras provas não exclui automaticamente a atenuante da confissão. O Tema 1194 do STJ trata do reconhecimento dessa circunstância.'),('penal-confissao-sumulas-545-630',13,'Correto. O art. 65, III, d, do Código Penal contempla a confissão espontânea da autoria do crime perante a autoridade como circunstância atenuante.'),('penal-confissao-sumulas-545-630',16,'Correto. O Tema 1194 do STJ discute os requisitos de incidência da atenuante da confissão espontânea na dosimetria da pena.'),('penal-confissao-sumulas-545-630',17,'Errado. Não é necessário que a confissão seja a única prova da autoria para o reconhecimento da atenuante; observe a orientação do Tema 1194 do STJ.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;